solution.solution.cpp:
#include <algorithm>
#include <cmath>
#include <vector>

struct Vector2 { float x, y; };
struct Rectangle { float x, y, width, height; };

float luminance(float r, float g, float b) { return 0.299f * r + 0.587f * g + 0.114f * b; }

namespace
{
    float smoothstep(float e0, float e1, float x)
    {
        const float t{ std::clamp((x - e0) / (e1 - e0), 0.0f, 1.0f) };
        return t * t * (3.0f - 2.0f * t);
    }
}

float vignette(float u, float v)
{
    return smoothstep(0.8f, 0.3f, std::sqrt((u - 0.5f) * (u - 0.5f) + (v - 0.5f) * (v - 0.5f)));
}

std::vector<float> blur3(const std::vector<float>& image, int w, int h)
{
    auto px = [w](const std::vector<float>& img, int x, int y) { return img[static_cast<std::size_t>(y * w + x)]; };
    std::vector<float> across(image.size()), out(image.size());
    for (int y{ 0 }; y < h; ++y)
        for (int x{ 0 }; x < w; ++x)
            across[static_cast<std::size_t>(y * w + x)] = (px(image, std::max(x - 1, 0), y) + px(image, x, y) + px(image, std::min(x + 1, w - 1), y)) / 3.0f;
    for (int y{ 0 }; y < h; ++y)
        for (int x{ 0 }; x < w; ++x)
            out[static_cast<std::size_t>(y * w + x)] = (px(across, x, std::max(y - 1, 0)) + px(across, x, y) + px(across, x, std::min(y + 1, h - 1))) / 3.0f;
    return out;
}

bool screenToNative(Vector2 mouse, Rectangle shown, int nativeW, int nativeH, int& px, int& py)
{
    if (mouse.x < shown.x || mouse.y < shown.y || mouse.x >= shown.x + shown.width || mouse.y >= shown.y + shown.height) return false;
    px = static_cast<int>(std::floor((mouse.x - shown.x) * nativeW / shown.width));
    py = static_cast<int>(std::floor((mouse.y - shown.y) * nativeH / shown.height));
    return true;
}

unitTests:
TEST("luminance") { CHECK_NEAR(luminance(1, 1, 1), 1.0, 1e-5); CHECK_NEAR(luminance(1, 0, 0), 0.299, 1e-6); CHECK_NEAR(luminance(0.5f, 0.5f, 0), 0.443, 1e-5); }
TEST("vignette") { CHECK_NEAR(vignette(0.5f, 0.5f), 1.0, 1e-6); CHECK_NEAR(vignette(0.0f, 0.0f), 0.0907, 1e-3); CHECK_NEAR(vignette(0.5f, 0.05f), 0.784, 1e-4); CHECK_NEAR(vignette(0.5f, -0.4f), 0.0, 1e-6); }
TEST("blurring a dot") {
    std::vector<float> img(9, 0.0f); img[4] = 9;
    const auto out = blur3(img, 3, 3);
    for (float v : out) CHECK_NEAR(v, 1.0, 1e-5);
}
TEST("clamping at the edges") { const auto out = blur3({ 0, 0, 3 }, 3, 1); CHECK_NEAR(out[0], 0.0, 1e-6); CHECK_NEAR(out[1], 1.0, 1e-6); CHECK_NEAR(out[2], 2.0, 1e-6); }
TEST("mouse to native pixels") {
    const Rectangle shown{ 43, 24, 1280, 720 }; int x = -1, y = -1;
    CHECK(screenToNative({ 43, 24 }, shown, 320, 180, x, y)); CHECK_EQ(x, 0); CHECK_EQ(y, 0);
    CHECK(screenToNative({ 1322.9f, 743.9f }, shown, 320, 180, x, y)); CHECK_EQ(x, 319); CHECK_EQ(y, 179);
    CHECK(screenToNative({ 50, 30 }, shown, 320, 180, x, y)); CHECK_EQ(x, 1); CHECK_EQ(y, 1);
    CHECK(!screenToNative({ 20, 30 }, shown, 320, 180, x, y)); CHECK(!screenToNative({ 1323, 30 }, shown, 320, 180, x, y));
}

